    std::string s;
    PutFixed32(&s, 0x01020304);
    // Expect little-endian: 04 03 02 01
    if (s.size()!=4) return 1;
    unsigned char a = s[0]; unsigned char b=s[1]; unsigned char c=s[2]; unsigned char d=s[3];
    return (a==0x04 && b==0x03 && c==0x02 && d==0x01) ? 0 : 1;
}

